messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Humanoid Animation - Three.js</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 10px;
            left: 10px;
            color: #ffffff;
            font-family: Arial, sans-serif;
            font-size: 14px;
            background: rgba(0,0,0,0.5);
            padding: 10px;
            border-radius: 5px;
        }
    </style>
</head>
<body>
    <div id="info">
        Animation Loop: <span id="state">Initializing...</span><br/>
        Time: <span id="timer">0.00s</span>
    </div>

    <!-- Import Three.js as ES module -->
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 3, 8);
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0x404040, 1.2); // Soft white
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 5);
        dirLight.castShadow = true;
        scene.add(dirLight);

        // --- Ground (Treadmill-style) ---
        const planeGeometry = new THREE.PlaneGeometry(10, 10);
        const planeMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x333333, 
            roughness: 0.8,
            metalness: 0.2
        });
        const plane = new THREE.Mesh(planeGeometry, planeMaterial);
        plane.rotation.x = -Math.PI / 2;
        plane.receiveShadow = true;
        scene.add(plane);

        // Add a subtle treadmill belt texture via geometry displacement
        const beltGeo = new THREE.PlaneGeometry(10, 10);
        const beltMat = new THREE.MeshStandardMaterial({
            color: 0x222222,
            roughness: 0.5,
            metalness: 0.1,
            side: THREE.DoubleSide
        });
        const belt = new THREE.Mesh(beltGeo, beltMat);
        belt.rotation.x = -Math.PI / 2;
        belt.position.y = 0.01; // Just above the base plane
        scene.add(belt);

        // --- Figure Group ---
        const figureGroup = new THREE.Group();
        scene.add(figureGroup);

        // Materials
        const skinMaterial = new THREE.MeshStandardMaterial({ color: 0xffccaa, roughness: 0.4 });
        const clothesMaterial = new THREE.MeshStandardMaterial({ color: 0x3366ff, roughness: 0.3 });

        // Helper function to create limbs
        function createLimb(width, height, material, group, isArm = false) {
            const geometry = new THREE.BoxGeometry(width, height, width);
            const mesh = new THREE.Mesh(geometry, material);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            group.add(mesh);
            return mesh;
        }

        // Torso
        const torso = createLimb(0.4, 0.8, clothesMaterial, figureGroup);
        torso.position.y = 1.6;

        // Head
        const head = createLimb(0.25, 0.3, skinMaterial, figureGroup);
        head.position.set(0, torso.position.y + torso.scale.y * 0.5 + 0.4, 0);

        // Arms
        const leftArm = createLimb(0.12, 0.7, skinMaterial, figureGroup, true);
        leftArm.position.set(-0.35, torso.position.y + torso.scale.y * 0.3, 0);
        const rightArm = createLimb(0.12, 0.7, skinMaterial, figureGroup, true);
        rightArm.position.set(0.35, torso.position.y + torso.scale.y * 0.3, 0);

        // Legs
        const leftLeg = createLimb(0.18, 0.75, skinMaterial, figureGroup);
        leftLeg.position.set(-0.2, torso.position.y - torso.scale.y * 0.35, 0);
        const rightLeg = createLimb(0.18, 0.75, skinMaterial, figureGroup);
        rightLeg.position.set(0.2, torso.position.y - torso.scale.y * 0.35, 0);

        // --- Animation State Variables ---
        let time = 0;
        let animationState = 'stand'; // stand, walk, run
        let cycleStartTime = 0;
        const totalCycleTime = 10;

        // --- Animation Logic ---
        function updateAnimation(dt) {
            time += dt;

            // Reset state every full cycle
            if (time >= totalCycleTime) {
                time = 0;
                animationState = 'stand';
                cycleStartTime = 0;
            }

            const t = time;
            const stateDuration = { stand: 2, walk: 3, run: 3 };
            const currentStateDuration = stateDuration[animationState];
            const progress = (t - cycleStartTime) / currentStateDuration;
            const ease = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2);

            // Update DOM
            const stateEl = document.getElementById('state');
            const timerEl = document.getElementById('timer');
            stateEl.textContent = animationState === 'stand' ? 'Stand' : (animationState === 'walk' ? 'Walk' : 'Run');
            timerEl.textContent = t.toFixed(2) + 's';

            // --- Movement ---
            // Slight forward lean during run
            let lean = 0;
            if (animationState === 'run') lean = -0.1;
            figureGroup.rotation.z = lean;

            // --- Limb Swings ---
            // Stand: nothing
            if (animationState === 'stand') {
                leftArm.rotation.x = 0;
                rightArm.rotation.x = 0;
                leftLeg.rotation.x = 0;
                rightLeg.rotation.x = 0;
            }
            else {
                // Walking: moderate swing, slower
                const walkSwing = Math.sin(t * 1.5) * 0.6;
                leftArm.rotation.x = walkSwing;
                rightArm.rotation.x = -walkSwing;
                leftLeg.rotation.x = walkSwing * 0.8;
                rightLeg.rotation.x = -walkSwing * 0.8;
            }
            else {
                // Running: faster, larger swing, more dynamic
                const runSwing = Math.sin(t * 3.0) * 1.0;
                leftArm.rotation.x = runSwing;
                rightArm.rotation.x = -runSwing;
                leftLeg.rotation.x = runSwing * 1.2;
                rightLeg.rotation.x = -runSwing * 1.2;
            }

            // --- State Transitions ---
            if (progress >= 1) {
                // Move to next state
                let nextState;
                if (animationState === 'stand') nextState = 'walk';
                else if (animationState === 'walk') nextState = 'run';
                else nextState = 'stand';

                animationState = nextState;
                cycleStartTime = t;
            }
        }

        // --- Resize Handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // --- Animation Loop ---
        const clock = new THREE.Clock();
        function animate() {
            requestAnimationFrame(animate);
            const dt = clock.getDelta();
            updateAnimation(dt);
            renderer.render(scene, camera);
        }

        animate();
    </script>
</body>
</html>
```
